<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {api,postJson} from '../api';
import {registerPageRefresher} from '../composables/pageRefresh';
import {preferences} from '../composables/preferences';
import {pointLabel,meterName} from '../composables/presentation';
const mapState=ref(null),points=ref([]),saved=ref({}),drafts=ref({}),dirty=ref(new Set()),selected=ref('A'),fullMap=ref(preferences.mapRange==='full'),busy=ref(false),message=ref(''),messageType=ref('');
const selectedMap=ref(''),activeMap=ref(''),mapName=ref(''),loadedMapName=ref('');
const mapDirty=computed(()=>Boolean(selectedMap.value)&&(selectedMap.value!==activeMap.value||mapName.value!==loadedMapName.value));
const current=computed(()=>drafts.value[selected.value]||null),origin=computed(()=>selected.value==='ORIGIN'),canSave=computed(()=>current.value&&(dirty.value.has(selected.value)||mapDirty.value)&&!busy.value);let unregister;
function inform(text,type=''){message.value=text;messageType.value=type;}
function field(key,event){if(!current.value)return;const value=event.target.value;current.value[key]=value===''?null:value;dirty.value=new Set(dirty.value).add(selected.value);message.value='';}
function position(value){if(!current.value||busy.value)return;Object.assign(current.value,{x_m:value.x,y_m:value.y});dirty.value=new Set(dirty.value).add(selected.value);}
function apply(data,pending={}){mapState.value=data;points.value=data.points||[];activeMap.value=data.active_map_id||data.map?.id||'';selectedMap.value=data.map?.id||activeMap.value;mapName.value=data.map?.name||data.maps?.find(m=>m.id===selectedMap.value)?.name||'巡检地图';loadedMapName.value=mapName.value;saved.value=Object.fromEntries(points.value.map(p=>[p.point,{...p}]));drafts.value=Object.fromEntries(points.value.map(p=>[p.point,pending[p.point]||{...p}]));if(!drafts.value[selected.value])selected.value=points.value[0]?.point||'A';}
async function fetchSettings(identifier=''){busy.value=true;try{apply(await api('/api/inspection-meter-settings'+(identifier?'?map_id='+encodeURIComponent(identifier):'')));inform('');return true;}catch(e){inform(e.message||'巡检设置读取失败，请重试。','error');return false;}finally{busy.value=false;}}
async function load(){if(dirty.value.size||mapDirty.value)return inform('请先保存或取消未保存的修改。');await fetchSettings();}
async function changeMap(){const previous=mapState.value?.map?.id||'';if(dirty.value.size||mapName.value!==loadedMapName.value){selectedMap.value=previous;return inform('请先保存或取消当前地图的修改。','error');}const identifier=selectedMap.value;if(!await fetchSettings(identifier))selectedMap.value=previous;}
async function cancel(){if(selectedMap.value!==activeMap.value){if(await fetchSettings(activeMap.value))dirty.value=new Set();return;}drafts.value[selected.value]={...saved.value[selected.value]};mapName.value=loadedMapName.value;const s=new Set(dirty.value);s.delete(selected.value);dirty.value=s;inform('');}
async function save(){
 if(!canSave.value)return;const p=current.value,savePoint=dirty.value.has(selected.value),changedMap=selectedMap.value!==activeMap.value;
 if(!mapName.value.trim())return inform('请填写地图名称。','error');
 if(savePoint){if(['x_m','y_m','yaw_deg'].some(k=>p[k]==null||p[k]===''||!Number.isFinite(Number(p[k]))))return inform('请填写有效的坐标与角度。','error');if(!origin.value&&!String(p.meter_name||'').trim())return inform('请填写仪表名称。','error');if(!origin.value&&p.normal_min==null&&p.normal_max==null)return inform('至少填写一个读数范围边界。','error');if(p.normal_min!=null&&p.normal_max!=null&&Number(p.normal_min)>Number(p.normal_max))return inform('下限不能大于上限。','error');}
 busy.value=true;try{const data=await postJson('/api/inspection-meter-settings',{map_id:selectedMap.value,map_name:mapName.value.trim(),save_point:savePoint,...(savePoint?{point:p.point,x_m:Number(p.x_m),y_m:Number(p.y_m),yaw_deg:Number(p.yaw_deg),meter_name:p.meter_name,meter_kind:p.meter_kind,normal_min:p.normal_min==null?null:Number(p.normal_min),normal_max:p.normal_max==null?null:Number(p.normal_max)}:{})});const pending=Object.fromEntries([...dirty.value].filter(id=>id!==p.point).map(id=>[id,{...drafts.value[id]}]));apply(data,pending);const s=new Set(dirty.value);s.delete(p.point);dirty.value=s;inform(changedMap?'保存成功，下次巡检将使用所选地图。':'保存成功','success');}catch(e){inform(e.message||'保存失败，修改内容已保留。','error');}finally{busy.value=false;}
}
onMounted(()=>{load();unregister=registerPageRefresher('meter-settings',load);});onBeforeUnmount(()=>unregister?.());
</script>
<template>
<div class="split-map">
 <UiCard title="巡检点位地图" glyph="map" class="map-panel"><div class="card-content"><div class="map-toolbar"><span>{{mapName||'巡检地图'}}</span><button class="btn" @click="fullMap=!fullMap"><UiIcon name="map" :size="15"/>{{fullMap?'仅看任务区域':'展开完整地图'}}</button></div><div class="map-stage" :class="{full:fullMap}"><div class="map-main"><TaskMap controls :map="mapState?.map" :points="Object.values(drafts)" :selected="selected" :full="fullMap" @position="position"/></div></div><div class="map-legend"><span><i class="legend-node"></i>巡检点位</span><span><i class="legend-line"></i>任务路线</span><span><i class="legend-node" style="background:#d4defc"></i>观察方向</span></div><div class="map-table"><div class="section-label">巡检点位</div><table><thead><tr><th>点位</th><th>仪表名称</th><th>类型</th><th>横向 X / 米</th><th>纵向 Y / 米</th><th>角度</th></tr></thead><tbody><tr v-for="p in Object.values(drafts)" :key="p.point" :class="{selected:p.point===selected}" tabindex="0" @click="selected=p.point" @keydown.enter="selected=p.point"><td>{{pointLabel(p.point)}}</td><td>{{p.point==='ORIGIN'?'返航点':meterName(p)}}</td><td>{{p.point==='ORIGIN'?'—':p.meter_kind==='pointer_meter'?'指针仪表':'数字仪表'}}</td><td class="number">{{p.x_m??'—'}}</td><td class="number">{{p.y_m??'—'}}</td><td class="number">{{p.yaw_deg??'—'}}°</td></tr></tbody></table></div></div></UiCard>
 <UiCard title="巡检设置" glyph="sliders" class="form-panel"><div class="card-content">
 <div class="field"><label for="inspection-map">选择地图</label><select id="inspection-map" v-model="selectedMap" :disabled="busy" @change="changeMap"><option v-for="map in mapState?.maps||[]" :key="map.id" :value="map.id">{{map.name}}</option></select></div>
 <div class="field"><label for="map-name">地图名称</label><input id="map-name" v-model="mapName" :disabled="busy" maxlength="80" @input="message=''"></div>
 <div class="form-divider"></div><div class="field"><label for="point">当前点位</label><select id="point" v-model="selected" :disabled="busy"><option v-for="p in points" :key="p.point" :value="p.point">{{pointLabel(p.point)}}{{p.point==='ORIGIN'?'':' · '+meterName(p)}}</option></select></div><template v-if="!origin"><div class="field"><label for="meter-name">仪表名称</label><input id="meter-name" :value="current?.meter_name||''" maxlength="120" :disabled="busy" @input="field('meter_name',$event)"></div><div class="field"><label for="meter-kind">仪表类型</label><select id="meter-kind" :value="current?.meter_kind" :disabled="busy" @change="field('meter_kind',$event)"><option value="digital_meter">数字仪表</option><option value="pointer_meter">指针仪表</option></select></div></template><div class="form-divider"></div><div class="form-section"><UiIcon name="map" :size="14"/>{{origin?'返航位置':'停车观察位置'}}</div><div class="field-row"><div class="field"><label for="x">横向 X</label><div class="input-suffix"><input id="x" :value="current?.x_m??''" type="number" step="any" :disabled="busy" @input="field('x_m',$event)"><span>米</span></div></div><div class="field"><label for="y">纵向 Y</label><div class="input-suffix"><input id="y" :value="current?.y_m??''" type="number" step="any" :disabled="busy" @input="field('y_m',$event)"><span>米</span></div></div></div><div class="field"><label for="angle">{{origin?'返航朝向':'观察角度'}}</label><div class="input-suffix"><input id="angle" :value="current?.yaw_deg??''" type="number" step="any" :disabled="busy" @input="field('yaw_deg',$event)"><span>°</span></div></div><template v-if="!origin"><div class="form-divider"></div><div class="form-section"><UiIcon name="alert" :size="14"/>读数范围</div><div class="field-row"><div class="field"><label for="minimum">下限</label><input id="minimum" :value="current?.normal_min??''" type="number" step="any" placeholder="不限" :disabled="busy" @input="field('normal_min',$event)"></div><div class="field"><label for="maximum">上限</label><input id="maximum" :value="current?.normal_max??''" type="number" step="any" placeholder="不限" :disabled="busy" @input="field('normal_max',$event)"></div></div></template><div v-if="message" class="note" :class="messageType" role="status">{{message}}</div></div><div class="action-row centered"><button class="btn primary" :disabled="!canSave" @click="save"><UiIcon name="check" :size="15"/>{{busy?'保存中…':'保存'}}</button><button class="btn" :disabled="(!dirty.has(selected)&&!mapDirty)||busy" @click="cancel"><UiIcon name="x" :size="15"/>取消</button></div></UiCard>
</div>
</template>
